const b=$input.first().json.body ?? {};
if(b.agentKey!=='ancfz'||!['quotation','invoice'].includes(b.documentType)) throw new Error('Invalid ANCFZ document type');
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function money(v){if(typeof v!=='number'||!Number.isFinite(v)||v<0)throw new Error('Invalid amount');return v.toFixed(2);}
if(!Array.isArray(b.lines)||b.lines.length<1||b.lines.length>40)throw new Error('Invalid lines');
const currency=String(b.currency??'');
if(!/^[A-Z]{3}$/.test(currency))throw new Error('Invalid currency');
const rows=b.lines.map(line=>'<tr><td>'+esc(String(line.label??'').slice(0,200))+'</td><td style="text-align:right">'+esc(currency)+' '+money(line.amount)+'</td></tr>').join('');
const total=b.lines.reduce((sum,line)=>sum+Number(line.amount),0);
if(typeof b.total!=='number'||!Number.isFinite(b.total)||Math.abs(total-b.total)>0.001)throw new Error('Total mismatch');
if(typeof b.documentNumber!=='string'||!b.documentNumber.trim()||b.documentNumber.length>100)throw new Error('Invalid document number');
if(b.documentType==='invoice') {
  // The authoritative Node payment ledger must supply this evidence only after
  // separately querying the gateway. Header Auth and these field checks are
  // defense-in-depth, NOT independent proof of a paid transaction.
  const p=b.paymentEvidence;
  if(b.paymentVerified!==true||!p||p.status!=='verified_test_payment'||
     p.provider!=='2checkout_mock'||p.ticketId!==b.ticketId||
     typeof b.quotationId!=='string'||
     !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b.quotationId)||
     p.quotationId!==b.quotationId||typeof p.providerReference!=='string'||
     !/^[A-Za-z0-9_-]{4,200}$/.test(p.providerReference)||
     p.currency!==currency||p.amount!==total.toFixed(2))
    throw new Error('Invoice blocked until correlated Node-verified TEST payment evidence exists');
}
if(typeof b.ticketId!=='string'||!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b.ticketId))
  throw new Error('Missing authorized ticket UUID');
if(typeof b.customerName!=='string'||!b.customerName.trim()||b.customerName.length>200)
  throw new Error('Invalid customer name');
const heading=b.documentType==='invoice'?'TEST PAYMENT INVOICE':'QUOTATION';
const note=b.documentType==='invoice'?'Sandbox payment confirmed. Not proof of real funds.':'This quotation is subject to ANCFZ approval and documented conditions.';
// The quotation source snapshot is immutable. Invoices receive it only from
// Node's matching, already verified quotation; payment proof remains separate.
let proposalHtml='';
if(b.documentType==='quotation'||b.documentType==='invoice'){
  const p=b.proposal;
  if(p!==undefined && p!==null){
    if(typeof p!=='object'||Array.isArray(p)||
       typeof p.packageDescription!=='string'||p.packageDescription.length>3000||
       (p.priceConditions!==null&&typeof p.priceConditions!=='string')||
       (typeof p.priceConditions==='string'&&p.priceConditions.length>3000)||
       !Array.isArray(p.requirements)||p.requirements.length>25)
      throw new Error('Invalid published quotation proposal');
    const requirements=p.requirements.map(r=>{
      if(!r||typeof r.label!=='string'||typeof r.value!=='string'||
         !r.label.trim()||!r.value.trim()||r.label.length>140||r.value.length>400)
        throw new Error('Invalid quoted requirement');
      return '<tr><td>'+esc(r.label)+'</td><td>'+esc(r.value)+'</td></tr>';
    }).join('');
    proposalHtml='<h3>Published package scope</h3>'+
      '<p>'+esc(p.packageDescription||'No catalog description is available.')+'</p>'+
      '<h3>Customer requirements '+(b.documentType==='invoice'?'from approved quotation':'for this quotation')+'</h3>'+
      (requirements?'<table><tr><th>Requirement</th><th>Requested value</th></tr>'+
        requirements+'</table>':'<p>No itemized requirements were attached.</p>')+
      '<h3>Published price conditions</h3>'+
      '<p>'+esc(p.priceConditions||'No additional price conditions published in this revision.')+'</p>'+
      '<h3>Scope and exclusions</h3>'+
      '<p>Only the published package and its expressly stated services are priced. '+
      'Workspace preferences and upgrades are not priced inclusions unless the '+
      'published package description or conditions explicitly say so. '+
      'Regulatory, licensing, visa and activity approvals remain subject to '+
      'ANCFZ and applicable authorities.</p>'+
      (b.documentType==='quotation'?
        '<h3>Next steps (development sandbox)</h3>'+
        '<p>After quotation review, synthetic passport and Emirates ID documents '+
        'are collected through private upload. Purchase consent, OTP, payment '+
        'verification and invoice issuance are separate steps. '+
        'This is not an official regulatory document checklist.</p>':'');
  }else{
    // Legacy queued quotations created before detailed scope publication.
    proposalHtml='<p class="muted">Detailed scope was not attached to this legacy quotation.</p>';
  }
}
let invoiceHtml='';
if(b.documentType==='invoice'){
  const identity=b.invoiceIdentity;
  if(!identity||typeof identity!=='object'||Array.isArray(identity)||
     typeof identity.emiratesIdLast4!=='string'||
     !/^\d{4}$/.test(identity.emiratesIdLast4)||
     !(identity.emiratesIdNumber===null||typeof identity.emiratesIdNumber==='string'))
    throw new Error('Invalid invoice identity evidence');
  const full=identity.emiratesIdNumber;
  if(full!==null && (!/^784\d{12}$/.test(full) ||
     !full.endsWith(identity.emiratesIdLast4)))
    throw new Error('Invalid invoice Emirates ID correlation');
  const displayed=full
    ?full.replace(/^(\d{3})(\d{4})(\d{7})(\d)$/,'$1-$2-$3-$4')
    :'XXXX-XXXX-XXXX-'+identity.emiratesIdLast4;
  invoiceHtml='<h3>Billing identity (private TEST document)</h3>'+
    '<table><tr><th>'+esc(full?'Emirates ID number':'Emirates ID (last 4 only)')+
    '</th><td>'+esc(displayed)+'</td></tr></table>'+
    '<h3>Payment verification</h3>'+
    '<table><tr><th>Quotation reference</th><td>'+esc(b.quotationId)+'</td></tr>'+
    '<tr><th>Sandbox provider reference</th><td>'+
    esc(b.paymentEvidence.providerReference)+'</td></tr>'+
    '<tr><th>Payment status</th><td>Independently verified TEST payment</td></tr></table>';
}
const html='<!doctype html><html><head><meta charset="UTF-8"><style>body{font:15px Arial,sans-serif;margin:36px;color:#172333}h1{color:#155db3}table{border-collapse:collapse;width:100%;margin-top:25px}th,td{border-bottom:1px solid #ccc;padding:10px;text-align:left}.muted{color:#536073;font-size:12px}</style></head><body><h1>ANCFZ</h1><h2>'+heading+'</h2><p>Document: '+esc(String(b.documentNumber??'').slice(0,100))+'</p><p>Customer: '+esc(String(b.customerName??'').slice(0,200))+'</p><table><tr><th>Description</th><th style="text-align:right">Amount</th></tr>'+rows+'</table><h3 style="text-align:right">Total: '+esc(currency)+' '+money(total)+'</h3>'+proposalHtml+invoiceHtml+'<p class="muted">'+note+'</p></body></html>';
return [{json:{documentType:b.documentType,documentNumber:String(b.documentNumber??''),ticketId:String(b.ticketId??'')},binary:{html:{data:Buffer.from(html,'utf8').toString('base64'),mimeType:'text/html',fileName:'index.html'}}}];

const pdf=await this.helpers.getBinaryDataBuffer(0,'data');
if(pdf.length<100 || pdf.length>5242880 || pdf.subarray(0,5).toString()!=='%PDF-')throw new Error('Invalid PDF bytes');
const original=$('Prepare Escaped HTML').first().json;
return [{json:{status:'generated',documentType:original.documentType,documentNumber:original.documentNumber,ticketId:original.ticketId,mimeType:'application/pdf',pdfBase64:pdf.toString('base64')}}];
